// Converte as habilidades para o formato da API e registra as traduções nos dicionários compartilhados.
const extraMonsters = extraMonsterData.map(({ name_pt: namePt, notes_pt: notesPt, art, ...monster }) => {
  const toEntries = (list) => list?.map(([name, entryNamePt, desc, entryDescPt]) => {
    if (!monsterEntryNamesPt[name]) monsterEntryNamesPt[name] = entryNamePt;
    monsterTextPt[desc] = entryDescPt;
    return { name, desc };
  });
  if (monster.notes && notesPt) monsterTextPt[monster.notes] = notesPt;
  return {
    ...monster,
    name_pt: namePt,
    slug: `extra-${monster.name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
    image: `${EXTRA_MONSTERS_IMAGE_BASE}/${art}/${encodeURIComponent(monster.name)}.webp`,
    special_abilities: toEntries(monster.special_abilities),
    actions: toEntries(monster.actions),
    reactions: toEntries(monster.reactions),
    legendary_actions: toEntries(monster.legendary_actions),
    lair_actions: toEntries(monster.lair_actions),
    document__title: EXTRA_MONSTERS_SOURCE,
    provider: "extra",
  };
});
